-- PMS v3.9.1 · Recordatorios de No-show Booking.com
create table if not exists public.notificaciones_booking_no_show(id uuid primary key default gen_random_uuid(),reserva_id uuid not null unique references public.reservas(id) on delete cascade,edificio_id uuid not null references public.edificios(id),fecha_entrada date not null,unidad_codigo text not null,huesped_nombre text not null,estado text not null default 'pendiente' check(estado in('pendiente','marcado_booking')),creada_en timestamptz not null default now(),creada_por uuid references public.perfiles(id),marcado_en timestamptz,marcado_por uuid references public.perfiles(id),mensaje_id uuid references public.buzon_mensajes(id),updated_at timestamptz not null default now());
create index if not exists idx_notif_booking_estado_edificio on public.notificaciones_booking_no_show(edificio_id,estado,fecha_entrada);
alter table public.notificaciones_booking_no_show enable row level security;
revoke all on public.notificaciones_booking_no_show from anon,authenticated;
grant select on public.notificaciones_booking_no_show to authenticated;
insert into public.configuracion(clave,valor,descripcion) values('booking_no_show_notificaciones_activo','true','Activar recordatorios automáticos de No-show de Booking.com'),('booking_no_show_hora','10:00','Hora de recordatorio Booking.com No-show (America/Santiago)'),('booking_no_show_mensaje','Hoy corresponde marcar como No-show en Booking.com: {huesped} · {edificio} · Unidad {unidad} · Entrada {fecha}.','Plantilla del recordatorio de Booking.com No-show') on conflict(clave) do nothing;
create or replace function public.pms_booking_no_show_trigger() returns trigger language plpgsql security definer set search_path=pg_catalog,public,auth,pg_temp as $$
declare v_edificio uuid;v_unidad text;v_nombre text;
begin
 if new.estado::text='no_show' and new.canal::text='booking' and (tg_op='INSERT' or old.estado::text is distinct from 'no_show') then
 select u.edificio_id,u.codigo,coalesce(nullif(new.huesped_nombre_copia,''),h.nombre_completo,'Huésped') into v_edificio,v_unidad,v_nombre from public.unidades u left join public.huespedes h on h.id=new.huesped_id where u.id=new.unidad_id;
 if v_edificio is not null then insert into public.notificaciones_booking_no_show(reserva_id,edificio_id,fecha_entrada,unidad_codigo,huesped_nombre,creada_por) values(new.id,v_edificio,new.fecha_entrada,coalesce(v_unidad,'—'),coalesce(v_nombre,'Huésped'),new.no_show_por) on conflict(reserva_id) do nothing;end if;
 end if;return new;end $$;
drop trigger if exists trg_pms_booking_no_show_notification on public.reservas;
create trigger trg_pms_booking_no_show_notification after insert or update of estado on public.reservas for each row execute function public.pms_booking_no_show_trigger();
create or replace function public.pms_booking_notif_access(p_edificio uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public,auth,pg_temp as $$
select exists(select 1 from public.perfiles p where p.id=auth.uid() and p.activo and lower(trim(p.rol::text)) in('gerencia','sysadmin','system_admin','systemadmin')) or exists(select 1 from public.perfiles_edificios pe join public.perfiles p on p.id=pe.perfil_id where p.id=auth.uid() and p.activo and pe.edificio_id=p_edificio)$$;
create or replace function public.pms_booking_notif_list() returns table(id uuid,reserva_id uuid,edificio_id uuid,edificio text,unidad text,huesped text,fecha_entrada date,estado text,creada_en timestamptz,marcado_en timestamptz,marcado_por uuid,marcado_por_nombre text,mensaje text) language plpgsql security definer set search_path=pg_catalog,public,auth,pg_temp as $$
declare v_hora text;v_activo text;v_template text;v_hoy date;v_now time;
begin
if auth.uid() is null then raise exception 'Sesión no válida';end if;
select valor into v_activo from public.configuracion where clave='booking_no_show_notificaciones_activo';select valor into v_hora from public.configuracion where clave='booking_no_show_hora';select valor into v_template from public.configuracion where clave='booking_no_show_mensaje';
v_hoy=(now() at time zone 'America/Santiago')::date;v_now=(now() at time zone 'America/Santiago')::time;
if coalesce(v_activo,'true')<>'true' or v_now<coalesce(v_hora,'10:00')::time then return;end if;
return query select n.id,n.reserva_id,n.edificio_id,e.nombre,n.unidad_codigo,n.huesped_nombre,n.fecha_entrada,n.estado,n.creada_en,n.marcado_en,n.marcado_por,p.nombre_completo,replace(replace(replace(replace(coalesce(v_template,'Hoy marcar No-show en Booking.com: {huesped} · {edificio} · {unidad} · {fecha}'),'{huesped}',n.huesped_nombre),'{edificio}',e.nombre),'{unidad}',n.unidad_codigo),'{fecha}',to_char(n.fecha_entrada,'DD-MM-YYYY')) from public.notificaciones_booking_no_show n join public.edificios e on e.id=n.edificio_id left join public.perfiles p on p.id=n.marcado_por join public.reservas r on r.id=n.reserva_id where n.fecha_entrada=v_hoy and r.estado::text='no_show' and r.canal::text='booking' and public.pms_booking_notif_access(n.edificio_id) order by n.estado,n.creada_en;
end $$;
create or replace function public.pms_booking_notif_mark(p_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,auth,pg_temp as $$
declare n public.notificaciones_booking_no_show%rowtype;v_user uuid;v_name text;
begin v_user=auth.uid();if v_user is null then raise exception 'Sesión no válida';end if;select * into n from public.notificaciones_booking_no_show where id=p_id for update;if not found then raise exception 'Notificación no encontrada';end if;if not public.pms_booking_notif_access(n.edificio_id) then raise exception 'Sin acceso a este edificio';end if;if n.estado='marcado_booking' then return;end if;select nombre_completo into v_name from public.perfiles where id=v_user;update public.notificaciones_booking_no_show set estado='marcado_booking',marcado_en=now(),marcado_por=v_user,updated_at=now() where id=p_id;insert into public.auditoria(tabla,registro_id,accion,datos_anteriores,datos_nuevos,usuario_id,fecha) values('notificaciones_booking_no_show',p_id,'UPDATE',to_jsonb(n),jsonb_build_object('estado','marcado_booking','marcado_en',now(),'marcado_por',v_user,'marcado_por_nombre',v_name,'reserva_id',n.reserva_id,'edificio_id',n.edificio_id),v_user,now());end $$;
create or replace function public.pms_booking_notif_config(p_activo boolean,p_hora text,p_mensaje text) returns void language plpgsql security definer set search_path=pg_catalog,public,auth,pg_temp as $$
declare v_user uuid;
begin v_user=auth.uid();if v_user is null or not exists(select 1 from public.perfiles where id=v_user and activo and lower(trim(rol::text)) in('gerencia','sysadmin','system_admin','systemadmin')) then raise exception 'Solo Gerencia o SysAdmin';end if;if p_hora !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Hora debe ser HH:MM';end if;if length(trim(p_mensaje)) not between 1 and 1000 then raise exception 'La plantilla debe tener entre 1 y 1000 caracteres';end if;
update public.configuracion set valor=p_activo::text,actualizado_por=v_user,actualizado_en=now() where clave='booking_no_show_notificaciones_activo';update public.configuracion set valor=p_hora,actualizado_por=v_user,actualizado_en=now() where clave='booking_no_show_hora';update public.configuracion set valor=p_mensaje,actualizado_por=v_user,actualizado_en=now() where clave='booking_no_show_mensaje';insert into public.auditoria(tabla,registro_id,accion,datos_anteriores,datos_nuevos,usuario_id,fecha) values('configuracion',gen_random_uuid(),'UPDATE',jsonb_build_object('booking_no_show_activo','config previo','hora','config previo','plantilla','config previo'),jsonb_build_object('activo',p_activo,'hora',p_hora,'mensaje',p_mensaje),v_user,now());end $$;
grant execute on function public.pms_booking_notif_list() to authenticated;grant execute on function public.pms_booking_notif_mark(uuid) to authenticated;grant execute on function public.pms_booking_notif_config(boolean,text,text) to authenticated;revoke execute on function public.pms_booking_notif_access(uuid) from public,anon,authenticated;revoke execute on function public.pms_booking_no_show_trigger() from public,anon,authenticated;